/// **What an order came to.** `ok` unless refused; `outcome` is the venue's word; a refusal's `reason` is the venue's
/// own sentence, `kind` the word a program branches on, `remedy` what to change and `docs` the page. `raw` is the
/// whole answer.
#[derive(Debug, Clone)]
pub struct Answer {
    pub ok: bool,
    pub outcome: String,
    pub reason: Option<String>,
    pub kind: Option<String>,
    pub remedy: Option<String>,
    pub docs: Option<String>,
    pub ticket: Option<i64>,
    pub order: Option<i64>,
    pub raw: Value,
}

impl Answer {
    pub fn of(raw: Value) -> Self {
        let pick = |k: &str| if raw[k].is_null() { raw["last_answer"][k].clone() } else { raw[k].clone() };
        let text = |k: &str| pick(k).as_str().map(str::to_owned);
        let outcome = text("outcome").filter(|o| !o.is_empty()).unwrap_or_else(|| "sent".into());
        Answer {
            ok: outcome != "refused",
            reason: text("reason"),
            kind: text("kind"),
            remedy: text("remedy"),
            docs: text("docs"),
            ticket: pick("ticket").as_f64().map(|n| n as i64),
            order: pick("order").as_f64().map(|n| n as i64),
            outcome,
            raw,
        }
    }
}

