/// **A workbench**: its orders, its book, its clock and its state, through either door.
pub struct Bench<'a> {
    c: &'a dyn Door,
    pub uri: String,
    pub name: Option<String>,
    raise: bool,
    markets: RefCell<Option<Vec<String>>>,
    mounted: std::cell::Cell<bool>,
}

impl<'a> Bench<'a> {
    pub fn new(client: &'a dyn Door, uri: &str, name: Option<String>, raise_refusals: bool) -> Self {
        Bench { c: client, uri: uri.to_owned(), name, raise: raise_refusals, markets: RefCell::new(None), mounted: std::cell::Cell::new(false) }
    }

    /// A workbench: the one named (its name or its address), else the selected one, else the first.
    pub fn open(client: &'a dyn Door, name: Option<&str>, raise_refusals: bool) -> Result<Self, Error> {
        let state = client.call("get_state", Value::Null)?;
        // A laboratory's workbenches, then a REAL account's (paper among them).
        let every: Vec<Value> = ["laboratories", "accounts"].iter().flat_map(|area| list(&state[*area])).flat_map(|home| list(&home["benches"])).collect();
        let pick = |b: &Value| Bench::new(client, b["uri"].as_str().unwrap_or_default(), b["name"].as_str().map(str::to_owned), raise_refusals);
        if let Some(name) = name {
            if let Some(b) = every.iter().find(|b| b["uri"] == name || b["name"] == name) {
                return Ok(pick(b));
            }
            let names: Vec<String> = every.iter().map(|b| format!("'{}'", b["name"].as_str().unwrap_or_default())).collect();
            return Err(Error::Other(format!("no workbench is named '{name}'; there are {}", if names.is_empty() { "none".into() } else { names.join(", ") })));
        }
        let first = every.first().ok_or_else(|| Error::Other("the workspace holds no laboratory workbench".into()))?;
        Ok(pick(every.iter().find(|b| state["selected"].is_string() && b["uri"] == state["selected"]).unwrap_or(first)))
    }

    /// The workbench's markets.
    pub fn markets(&self) -> Result<Vec<String>, Error> {
        if self.markets.borrow().is_none() {
            let state = self.read_uri(&self.uri)?;
            let ms = list(&state["markets"]).iter().filter_map(|m| m.as_str().or_else(|| m["symbol"].as_str()).map(str::to_owned)).collect();
            *self.markets.borrow_mut() = Some(ms);
        }
        Ok(self.markets.borrow().clone().unwrap_or_default())
    }

    /// Every read through the resource_read tool: a door is anything with `call`.
    fn read_uri(&self, uri: &str) -> Result<Value, Error> {
        self.c.call("resource_read", serde_json::json!({"uri": uri}))
    }

    /// A workbench with no engine mounted (a clone, through the application) is selected - the window shows it, which
    /// is how Bentrix mounts one - and waited for, at most a minute.
    fn mount(&self) -> Result<(), Error> {
        if self.mounted.replace(true) {
            return Ok(());
        }
        let none = |b: &Self| -> Result<bool, Error> { Ok(b.read_uri(&b.uri)?["engine"] == "none") };
        if !none(self)? {
            return Ok(());
        }
        self.c.call("select_bench", serde_json::json!({"bench": self.uri}))?;
        for _ in 0..600 {
            if !none(self)? {
                return Ok(());
            }
            std::thread::sleep(std::time::Duration::from_millis(100));
        }
        Ok(())
    }

    fn symbol(&self, given: Value) -> Result<String, Error> {
        if let Some(s) = given.as_str() {
            return Ok(s.to_owned());
        }
        let ms = self.markets()?;
        match ms.as_slice() {
            [one] => Ok(one.clone()),
            _ => Err(Error::Other(format!("this workbench holds {} markets ({}): name the symbol", ms.len(), ms.join(", ")))),
        }
    }

    /// A refusal is an answer, or - opened with `raise_refusals` - an `Error::Tool` whose `machine` is its kind.
    fn answered(&self, raw: Value) -> Result<Answer, Error> {
        let a = Answer::of(raw);
        if !a.ok && self.raise {
            return Err(Error::Tool { tool: "order".into(), message: a.reason.clone().unwrap_or_else(|| a.outcome.clone()), machine: a.kind.clone() });
        }
        Ok(a)
    }

    fn read(&self, tail: &str, after: Option<&str>) -> Result<Value, Error> {
        let uri = format!("{}/{tail}{}", self.uri, after.map(|a| format!("?after={}", escape(a))).unwrap_or_default());
        self.read_uri(&uri)
    }

    fn stream(&self, tail: &str) -> Result<Vec<Value>, Error> {
        let mut all = Vec::new();
        let mut after: Option<String> = None;
        loop {
            let page = self.read(tail, after.as_deref())?;
            let items = list(&page["items"]);
            if items.is_empty() {
                return Ok(all);
            }
            all.extend(items);
            match page["next"].as_str() {
                Some(next) => after = Some(next.to_owned()),
                None => return Ok(all),
            }
        }
    }

    /// To the next close: a workbench that has lived through no tick steps one first (a jump never invents a first
    /// quote), then a candle of the interval; the closed candle is read back from the window.
    fn step_(&self, interval: Value, sym: Value) -> Result<Option<Value>, Error> {
        let tf = interval.as_str().unwrap_or("M1").to_owned();
        let s = sym.as_str().unwrap_or_default().to_owned();
        let stood = self.read_uri(&self.uri)?["cursor_ms"].clone();
        let q = quote_of(&self.read("quotes", None)?, &s);
        if q.as_ref().is_none_or(|q| q["at_ms"].is_null()) {
            self.c.call("replay_step", serde_json::json!({"bench": self.uri, "unit": "tick", "n": 1}))?;
        }
        let now = self.c.call("replay_step", serde_json::json!({"bench": self.uri, "unit": "candle", "n": 1, "timeframe": tf}))?["cursor_ms"].clone();
        if now.is_null() || now == stood {
            return Ok(None);
        }
        let got = self.c.call("bars_window", serde_json::json!({"bench": self.uri, "symbol": s, "frames": [tf], "limit": 1}))?;
        let rows = list(&got["markets"][&s][&tf]["rows"]);
        Ok(rows.last().map(|r| serde_json::json!({"time": r[0], "open": r[1], "high": r[2], "low": r[3], "close": r[4], "volume": r[5]})))
    }

    /// A market buy of lots; sl and tp as prices.
    pub fn buy(&self, lots: f64, opts: impl Into<BuyOptions>) -> Result<Answer, Error> {
        self.mount()?;
        let opts = opts.into();
        let mut a = Map::new();
        a.insert("bench".into(), Value::from(self.uri.as_str()));
        a.insert("side".into(), literal("\"buy\""));
        put(&mut a, "volume", Value::from(lots));
        put(&mut a, "symbol", Value::from(self.symbol(opt(&opts.values, "symbol"))?));
        put(&mut a, "sl", opt(&opts.values, "sl"));
        put(&mut a, "tp", opt(&opts.values, "tp"));
        put(&mut a, "tag", opt(&opts.values, "tag"));
        put(&mut a, "group", opt(&opts.values, "group"));
        self.answered(self.c.call("order_market", Value::Object(a))?)
    }

    /// A market sell of lots; sl and tp as prices.
    pub fn sell(&self, lots: f64, opts: impl Into<SellOptions>) -> Result<Answer, Error> {
        self.mount()?;
        let opts = opts.into();
        let mut a = Map::new();
        a.insert("bench".into(), Value::from(self.uri.as_str()));
        a.insert("side".into(), literal("\"sell\""));
        put(&mut a, "volume", Value::from(lots));
        put(&mut a, "symbol", Value::from(self.symbol(opt(&opts.values, "symbol"))?));
        put(&mut a, "sl", opt(&opts.values, "sl"));
        put(&mut a, "tp", opt(&opts.values, "tp"));
        put(&mut a, "tag", opt(&opts.values, "tag"));
        put(&mut a, "group", opt(&opts.values, "group"));
        self.answered(self.c.call("order_market", Value::Object(a))?)
    }

    /// A pending order: kind buy_limit, sell_limit, buy_stop, sell_stop, buy_stop_limit or sell_stop_limit.
    pub fn pending(&self, kind: impl Into<String>, price: f64, lots: f64, opts: impl Into<PendingOptions>) -> Result<Answer, Error> {
        self.mount()?;
        let opts = opts.into();
        let mut a = Map::new();
        a.insert("bench".into(), Value::from(self.uri.as_str()));
        put(&mut a, "kind", Value::from(Into::<String>::into(kind)));
        put(&mut a, "price", Value::from(price));
        put(&mut a, "volume", Value::from(lots));
        put(&mut a, "symbol", Value::from(self.symbol(opt(&opts.values, "symbol"))?));
        put(&mut a, "sl", opt(&opts.values, "sl"));
        put(&mut a, "tp", opt(&opts.values, "tp"));
        put(&mut a, "stop_limit", opt(&opts.values, "stop_limit"));
        put(&mut a, "expires_ms", opt(&opts.values, "expires"));
        put(&mut a, "tag", opt(&opts.values, "tag"));
        put(&mut a, "group", opt(&opts.values, "group"));
        self.answered(self.c.call("order_pending", Value::Object(a))?)
    }

    /// Only what is named changes: a position's or an order's stop, target, or a pending order's price; 0 removes a level.
    pub fn modify(&self, ticket: impl Into<Ticket>, opts: impl Into<ModifyOptions>) -> Result<Answer, Error> {
        self.mount()?;
        let opts = opts.into();
        let mut a = Map::new();
        a.insert("bench".into(), Value::from(self.uri.as_str()));
        put(&mut a, "ticket", Into::<Ticket>::into(ticket).0);
        put(&mut a, "sl", opt(&opts.values, "sl"));
        put(&mut a, "tp", opt(&opts.values, "tp"));
        put(&mut a, "price", opt(&opts.values, "price"));
        self.answered(self.c.call("order_modify", Value::Object(a))?)
    }

    /// Close a position, all of it or lots of it, or cancel a pending order.
    pub fn close(&self, ticket: impl Into<Ticket>, opts: impl Into<CloseOptions>) -> Result<Answer, Error> {
        self.mount()?;
        let opts = opts.into();
        let mut a = Map::new();
        a.insert("bench".into(), Value::from(self.uri.as_str()));
        put(&mut a, "ticket", Into::<Ticket>::into(ticket).0);
        put(&mut a, "volume", opt(&opts.values, "lots"));
        self.answered(self.c.call("order_close", Value::Object(a))?)
    }

    /// Close every position, or one market's, or one group's; nothing open is an answer, not a refusal.
    pub fn close_all(&self, opts: impl Into<CloseAllOptions>) -> Result<Answer, Error> {
        self.mount()?;
        let opts = opts.into();
        let mut a = Map::new();
        a.insert("bench".into(), Value::from(self.uri.as_str()));
        put(&mut a, "symbol", opt(&opts.values, "symbol"));
        put(&mut a, "group", opt(&opts.values, "group"));
        self.answered(self.c.call("order_close_all", Value::Object(a))?)
    }

    /// Close a position and open the same size the other way, as one act.
    pub fn reverse(&self, ticket: impl Into<Ticket>) -> Result<Answer, Error> {
        self.mount()?;
        let mut a = Map::new();
        a.insert("bench".into(), Value::from(self.uri.as_str()));
        put(&mut a, "ticket", Into::<Ticket>::into(ticket).0);
        self.answered(self.c.call("order_reverse", Value::Object(a))?)
    }

    /// Stop following a position's trailing stop; its stop stays where the trail left it.
    pub fn untrail(&self, ticket: impl Into<Ticket>) -> Result<Answer, Error> {
        self.mount()?;
        let mut a = Map::new();
        a.insert("bench".into(), Value::from(self.uri.as_str()));
        put(&mut a, "ticket", Into::<Ticket>::into(ticket).0);
        self.answered(self.c.call("order_untrail", Value::Object(a))?)
    }

    /// A group of orders under a label: its number, for buy's and close_all's group.
    pub fn group(&self, label: impl Into<String>) -> Result<Option<i64>, Error> {
        self.mount()?;
        let mut a = Map::new();
        a.insert("bench".into(), Value::from(self.uri.as_str()));
        put(&mut a, "label", Value::from(Into::<String>::into(label)));
        Ok(self.c.call("group_open", Value::Object(a))?["group"].as_f64().map(|n| n as i64))
    }

    /// A trailing stop at points from the price, the venue's own.
    pub fn trail(&self, ticket: impl Into<Ticket>, points: f64) -> Result<Answer, Error> {
        self.mount()?;
        let mut a = Map::new();
        a.insert("bench".into(), Value::from(self.uri.as_str()));
        put(&mut a, "ticket", Into::<Ticket>::into(ticket).0);
        put(&mut a, "points", Value::from(points));
        self.answered(self.c.call("order_trail", Value::Object(a))?)
    }

    /// Cancel a pending order; the same act as close on an order's ticket.
    pub fn cancel(&self, ticket: impl Into<Ticket>) -> Result<Answer, Error> {
        self.mount()?;
        let mut a = Map::new();
        a.insert("bench".into(), Value::from(self.uri.as_str()));
        put(&mut a, "ticket", Into::<Ticket>::into(ticket).0);
        self.answered(self.c.call("order_close", Value::Object(a))?)
    }

    /// What an order would cost and hold - its margin, its money a point, its price - sending nothing.
    pub fn preview(&self, side: impl Into<String>, lots: f64, opts: impl Into<PreviewOptions>) -> Result<Value, Error> {
        self.mount()?;
        let opts = opts.into();
        let mut a = Map::new();
        a.insert("bench".into(), Value::from(self.uri.as_str()));
        put(&mut a, "side", Value::from(Into::<String>::into(side)));
        put(&mut a, "volume", Value::from(lots));
        put(&mut a, "symbol", Value::from(self.symbol(opt(&opts.values, "symbol"))?));
        Ok(self.c.call("order_preview", Value::Object(a))?)
    }

    /// What the book holds by market: lots net and gross, each market's notional, the account's ratios.
    pub fn exposure(&self) -> Result<Value, Error> {
        self.mount()?;
        self.read("exposure", None)
    }

    /// The last closed candles of interval, oldest first.
    pub fn bars(&self, opts: impl Into<BarsOptions>) -> Result<Vec<Value>, Error> {
        self.mount()?;
        let opts = opts.into();
        let mut a = Map::new();
        a.insert("bench".into(), Value::from(self.uri.as_str()));
        put(&mut a, "timeframe", or_default(opt(&opts.values, "interval"), "\"M1\""));
        put(&mut a, "limit", or_default(opt(&opts.values, "limit"), "100"));
        put(&mut a, "symbol", Value::from(self.symbol(opt(&opts.values, "symbol"))?));
        let page = self.c.call("bars_get", Value::Object(a))?;
        let mut rows = list(&page["bars"]);
        if page["last_forming"] == true {
            rows.pop();
        }
        Ok(rows)
    }

    /// The book: positions, orders and the account.
    pub fn book(&self) -> Result<Value, Error> {
        self.mount()?;
        self.read("book", None)
    }

    /// The open positions.
    pub fn positions(&self) -> Result<Vec<Value>, Error> {
        self.mount()?;
        Ok(list(&self.read("book", None)?["positions"]))
    }

    /// The resting orders.
    pub fn orders(&self) -> Result<Vec<Value>, Error> {
        self.mount()?;
        Ok(list(&self.read("book", None)?["orders"]))
    }

    /// The account: balance, equity, margin, free margin, currency.
    pub fn account(&self) -> Result<Value, Error> {
        self.mount()?;
        self.read("account", None)
    }

    /// Every deal, oldest first.
    pub fn deals(&self) -> Result<Vec<Value>, Error> {
        self.mount()?;
        self.stream("deals")
    }

    /// The venue's event log, oldest first.
    pub fn events(&self) -> Result<Vec<Value>, Error> {
        self.mount()?;
        self.stream("events")
    }

    /// Every order the workbench was sent, oldest first: what it became and when.
    pub fn order_history(&self) -> Result<Vec<Value>, Error> {
        self.mount()?;
        self.stream("orders")
    }

    /// The market's bid and ask at the clock, or none.
    pub fn quote(&self, opts: impl Into<QuoteOptions>) -> Result<Option<Value>, Error> {
        self.mount()?;
        let opts = opts.into();
        let sym = Value::from(self.symbol(opt(&opts.values, "symbol"))?);
        Ok(quote_of(&self.read("quotes", None)?, sym.as_str().unwrap_or_default()))
    }

    /// A market's facts as numbers: digits, point, contract, volumes, stops level, swaps, sessions.
    pub fn spec(&self, opts: impl Into<SpecOptions>) -> Result<Value, Error> {
        self.mount()?;
        let opts = opts.into();
        let mut a = Map::new();
        a.insert("bench".into(), Value::from(self.uri.as_str()));
        put(&mut a, "symbol", Value::from(self.symbol(opt(&opts.values, "symbol"))?));
        Ok(self.c.call("symbol_info", Value::Object(a))?)
    }

    /// Several timeframes at once, closed candles only, each with its forming candle.
    pub fn window(&self, frames: &[&str], opts: impl Into<WindowOptions>) -> Result<Value, Error> {
        self.mount()?;
        let opts = opts.into();
        let mut a = Map::new();
        a.insert("bench".into(), Value::from(self.uri.as_str()));
        a.insert("include_forming".into(), literal("true"));
        put(&mut a, "frames", Value::from(frames.iter().map(|s| Value::from(*s)).collect::<Vec<_>>()));
        put(&mut a, "limit", or_default(opt(&opts.values, "limit"), "100"));
        put(&mut a, "symbol", Value::from(self.symbol(opt(&opts.values, "symbol"))?));
        Ok(self.c.call("bars_window", Value::Object(a))?)
    }

    /// Its conditions and their digest.
    pub fn manifest(&self) -> Result<Value, Error> {
        self.mount()?;
        let mut a = Map::new();
        a.insert("bench".into(), Value::from(self.uri.as_str()));
        Ok(self.c.call("bench_manifest", Value::Object(a))?)
    }

    /// To the next close of interval: the closed candle and where the clock stands, or none where it moves no further.
    pub fn step(&self, opts: impl Into<StepOptions>) -> Result<Option<Value>, Error> {
        self.mount()?;
        let opts = opts.into();
        self.step_(or_default(opt(&opts.values, "interval"), "\"M1\""), Value::from(self.symbol(opt(&opts.values, "symbol"))?))
    }

    /// Forward to a moment, at most the days' last; where the clock stands.
    pub fn advance(&self, to: i64) -> Result<Option<i64>, Error> {
        self.mount()?;
        let mut a = Map::new();
        a.insert("bench".into(), Value::from(self.uri.as_str()));
        a.insert("stop_at_end".into(), literal("true"));
        put(&mut a, "to_ms", Value::from(to));
        Ok(self.c.call("replay_seek", Value::Object(a))?["cursor_ms"].as_f64().map(|n| n as i64))
    }

    /// Back to a moment; refused with its door when that would undo a deal, unless undo_deals.
    pub fn rewind(&self, to: i64, opts: impl Into<RewindOptions>) -> Result<Value, Error> {
        self.mount()?;
        let opts = opts.into();
        let mut a = Map::new();
        a.insert("bench".into(), Value::from(self.uri.as_str()));
        put(&mut a, "to_ms", Value::from(to));
        put(&mut a, "undo_deals", or_default(opt(&opts.values, "undo_deals"), "false"));
        Ok(self.c.call("replay_seek", Value::Object(a))?)
    }

    /// A checkpoint to a file.
    pub fn save(&self, name: impl Into<String>) -> Result<Value, Error> {
        self.mount()?;
        let mut a = Map::new();
        a.insert("bench".into(), Value::from(self.uri.as_str()));
        put(&mut a, "path", Value::from(Into::<String>::into(name)));
        Ok(self.c.call("checkpoint_save", Value::Object(a))?)
    }

    /// A checkpoint back, refused under other conditions.
    pub fn load(&self, name: impl Into<String>) -> Result<Value, Error> {
        self.mount()?;
        let mut a = Map::new();
        a.insert("bench".into(), Value::from(self.uri.as_str()));
        put(&mut a, "path", Value::from(Into::<String>::into(name)));
        Ok(self.c.call("checkpoint_load", Value::Object(a))?)
    }

    /// A workbench alike, in this one's state by default.
    pub fn clone(&self, opts: impl Into<CloneOptions>) -> Result<Bench<'a>, Error> {
        self.mount()?;
        let opts = opts.into();
        let mut a = Map::new();
        a.insert("bench".into(), Value::from(self.uri.as_str()));
        put(&mut a, "state", or_default(opt(&opts.values, "state"), "true"));
        put(&mut a, "name", opt(&opts.values, "name"));
        let made = self.c.call("bench_clone", Value::Object(a))?;
        Ok(Bench::new(self.c, made["uri"].as_str().unwrap_or_default(), made["name"].as_str().map(str::to_owned), self.raise))
    }

    /// Keep where it stands, to watch on the chart: a clone in its state, under a name.
    pub fn keep(&self, name: impl Into<String>) -> Result<Bench<'a>, Error> {
        self.mount()?;
        let mut a = Map::new();
        a.insert("bench".into(), Value::from(self.uri.as_str()));
        a.insert("state".into(), literal("true"));
        put(&mut a, "name", Value::from(Into::<String>::into(name)));
        let made = self.c.call("bench_clone", Value::Object(a))?;
        Ok(Bench::new(self.c, made["uri"].as_str().unwrap_or_default(), made["name"].as_str().map(str::to_owned), self.raise))
    }

}
